            Lines.Add($"            case \"{Escape(Scene.ClassFullyQualifiedName)}\": Key = global::{Scene.ClassFullyQualifiedName}.EntityPayload; return true;");
        }
        Lines.AddRange([
            "            default: Key = default; return false;",
            "        }",
            "    }",
            "    public bool TryApply(global::CSharpGameEngine.World.WorldCellTransition Transition, global::System.Collections.Generic.IReadOnlyDictionary<global::CSharpGameEngine.Contracts.WorldCellId, global::CSharpGameEngine.World.LoadedWorldCell> LoadedCells, out string Error) {",
            "        if (Transition is null) { Error = \"World-cell transition is required.\"; return false; }",
            "        if (LoadedCells is null) { Error = \"Loaded-cell set is required.\"; return false; }",
            "        var Payloads = new global::System.Collections.Generic.Dictionary<global::CSharpGameEngine.Contracts.WorldCellId, global::CSharpGameEngine.Contracts.AssetKey>();",
            "        var Attempted = new global::System.Collections.Generic.List<global::CSharpGameEngine.Contracts.WorldCellId>();",
            "        ref global::CSharpGameEngine.Entities.World World = ref this.Owner.World;",
            "        try {",
            "            foreach (global::CSharpGameEngine.Contracts.WorldCellId Cell in Transition.ToActivate) {",
            "                if (!LoadedCells.TryGetValue(Cell, out global::CSharpGameEngine.World.LoadedWorldCell? Loaded)) throw new global::System.IO.InvalidDataException(\"Activation cell has no loaded artifact set: \" + Cell);",
            "                if (!Loaded.Artifacts.TryGetValue(Loaded.Definition.EntityPayload, out global::CSharpGameEngine.Content.ContentArtifact? Artifact)) throw new global::System.IO.InvalidDataException(\"Activation cell omits its entity payload artifact: \" + Cell);",
            "                if (!global::CSharpGameEngine.World.WorldCellEntityPayloadCodec.TryRead(Artifact, out global::CSharpGameEngine.Contracts.AssetKey Payload, out string PayloadError)) throw new global::System.IO.InvalidDataException(PayloadError);",
            "                if (Payload != Loaded.Definition.EntityPayload) throw new global::System.IO.InvalidDataException(\"Entity payload artifact identity does not match the cell manifest.\");",
            "                if (!IsKnownPayload(Payload)) throw new global::System.IO.InvalidDataException(\"No generated C# Scene owns entity payload: \" + Payload);",
            "                if (World.HasOwnedCell(Cell)) throw new global::System.InvalidOperationException(\"ECS World already owns entities for activation cell: \" + Cell);",
            "                Payloads.Add(Cell, Payload);",
            "            }",
            "            foreach (global::CSharpGameEngine.Contracts.WorldCellId Cell in Transition.ToDeactivate) {",
            "                if (!World.HasOwnedCell(Cell)) throw new global::System.InvalidOperationException(\"ECS World has no owned entities for deactivation cell: \" + Cell);",
            "            }",
            "            foreach (global::CSharpGameEngine.Contracts.WorldCellId Cell in Transition.ToActivate) {",
            "                Attempted.Add(Cell);",
