            "            foreach (global::CSharpGameEngine.Contracts.WorldCellId Cell in Transition.ToDeactivate) {",
            "                _ = World.UnloadCell(Cell);",
            "            }",
            "            Error = string.Empty;",
            "            return true;",
            "        } catch (global::System.Exception Exception) {",
            "            for (var Index = Attempted.Count - 1; Index >= 0; Index--) _ = World.UnloadCell(Attempted[Index]);",
            "            Error = Exception.Message;",
            "            return false;",
            "        }",
            "    }",
            "    private static bool IsKnownPayload(global::CSharpGameEngine.Contracts.AssetKey Payload) {",
        ]);
        foreach(var Scene in Scenes.OrderBy(static Scene=>Scene.ClassFullyQualifiedName,StringComparer.Ordinal)){
            Lines.Add($"        if (Payload == global::{Scene.ClassFullyQualifiedName}.EntityPayload) return true;");
        }
        Lines.AddRange([
            "        return false;",
            "    }",
            "    private static void Instantiate(global::CSharpGameEngine.Contracts.AssetKey Payload, ref global::CSharpGameEngine.Entities.World World, global::CSharpGameEngine.Contracts.WorldCellId Cell) {",
        ]);
        foreach(var Scene in Scenes.OrderBy(static Scene=>Scene.ClassFullyQualifiedName,StringComparer.Ordinal)){
            Lines.Add($"        if (Payload == global::{Scene.ClassFullyQualifiedName}.EntityPayload) {{ global::{Scene.ClassFullyQualifiedName}.InstantiateCell(ref World, Cell); return; }}");
